"""Version-specific schemas for the mesh/timeline subset generated by this tool.

Verified against the official 3.8 and 4.2 SkeletonJson and TextureAtlas readers.
This intentionally does not claim to convert arbitrary third-party skeletons.
"""
from __future__ import annotations

import copy
import math
import re

SPINE_TARGETS = {"3.8": "3.8.99", "4.0": "4.0.56", "4.2": "4.2.43"}
CANONICAL_SPINE_VERSION = SPINE_TARGETS["4.0"]
FORMAT_SOURCES = {
    "3.8": [
        "https://github.com/EsotericSoftware/spine-runtimes/blob/3.8/spine-ts/core/src/SkeletonJson.ts",
        "https://github.com/EsotericSoftware/spine-runtimes/blob/3.8/spine-ts/core/src/TextureAtlas.ts",
    ],
    "4.0": [
        "https://github.com/EsotericSoftware/spine-runtimes/blob/4.0/spine-ts/spine-core/src/SkeletonJson.ts",
    ],
    "4.2": [
        "https://github.com/EsotericSoftware/spine-runtimes/blob/4.2/spine-ts/spine-core/src/SkeletonJson.ts",
        "https://github.com/EsotericSoftware/spine-runtimes/blob/4.2/spine-ts/spine-core/src/TextureAtlas.ts",
    ],
}


def normalize_spine_version(value: str = CANONICAL_SPINE_VERSION) -> str:
    text = str(value).strip()
    if text in SPINE_TARGETS:
        return SPINE_TARGETS[text]
    if re.fullmatch(r"(?:3\.8|4\.0|4\.2)\.\d{1,3}", text):
        return text
    raise ValueError("Spine 版本需為 3.8、4.0 或 4.2。")


def spine_family(version: str) -> str:
    return ".".join(normalize_spine_version(version).split(".")[:2])


def animation_key_times(skeleton: dict) -> tuple[float, ...]:
    """All actual key times, including culling/color/bone/deform timelines."""
    result = set()

    def visit(value):
        if isinstance(value, dict):
            time = value.get("time")
            if isinstance(time, (int, float)) and not isinstance(time, bool) and math.isfinite(time):
                result.add(float(time))
            for child in value.values():
                visit(child)
        elif isinstance(value, (list, tuple)):
            for child in value:
                visit(child)

    visit(skeleton.get("animations", {}))
    return tuple(sorted(result))


def select_native_safe_fps(skeleton: dict, version: str | None = None) -> int:
    """Avoid native editor near-integer-frame key snapping without moving keys.

    Native 3.8.99 and 4.2.43 round imported times near whole frames. A different timeline
    FPS changes only the editor's frame labels, leaving seconds and geometry
    intact. Actual native probes measured a 0.01-frame window; 0.011 is used as
    a conservative margin. Float32 noise on already exact frames is harmless.
    """
    family = spine_family(version or skeleton.get("skeleton", {}).get("spine", "3.8.99"))
    times = animation_key_times(skeleton)
    preferred = (30, 60, 120, 240)
    candidates = (*preferred, *(fps for fps in range(30, 241) if fps not in preferred))
    for fps in candidates:
        safe = True
        for time in times:
            frame = time * fps
            distance = abs(frame - round(frame))
            if 1e-5 < distance < 0.011:
                safe = False
                break
        if safe:
            return fps
    raise ValueError(f"此動畫的關鍵格太接近 Spine {family} 的整數影格，無法安全匯入；請調整動畫長度後重試。")


def select_native_safe_fps_38(skeleton: dict) -> int:
    """Backward-compatible name for callers that explicitly target 3.8."""
    return select_native_safe_fps(skeleton, "3.8.99")


def _normalized_curve(first: dict, second: dict, value_key: str = "value") -> tuple | str | None:
    curve = first.get("curve")
    if curve is None or curve == "stepped":
        return curve
    if not isinstance(curve, (list, tuple)) or len(curve) != 4:
        raise ValueError("無法轉換此 Bezier 曲線至 Spine 3.8。")
    t0, t1 = float(first.get("time", 0)), float(second.get("time", 0))
    v0, v1 = float(first.get(value_key, 0)), float(second.get(value_key, 0))
    if t1 <= t0:
        raise ValueError("動畫關鍵格時間需依序遞增。")
    if abs(v1 - v0) < 1e-12:
        if max(abs(float(curve[1]) - v0), abs(float(curve[3]) - v0)) > 1e-7:
            raise ValueError("Spine 3.8 無法以相同端點表達此獨立值曲線。")
        return ((float(curve[0]) - t0) / (t1 - t0), 0.0,
                (float(curve[2]) - t0) / (t1 - t0), 1.0)
    result = ((float(curve[0]) - t0) / (t1 - t0), (float(curve[1]) - v0) / (v1 - v0),
              (float(curve[2]) - t0) / (t1 - t0), (float(curve[3]) - v0) / (v1 - v0))
    if not all(math.isfinite(value) for value in result):
        raise ValueError("Bezier 曲線含有無效數值。")
    return result


def _set_curve_38(frame: dict, curve) -> None:
    if curve is None:
        return
    if curve == "stepped":
        frame["curve"] = "stepped"
        return
    # 3.8.99 uses a numeric first control plus c2/c3/c4, not the 4.x
    # absolute-coordinate array or the legacy pre-3.8 array representation.
    frame.update({key: round(float(value), 12)
                  for key, value in zip(("curve", "c2", "c3", "c4"), curve)})


def _curve_nodes(first: dict, second: dict) -> list[tuple]:
    t0, t1 = float(first.get("time", 0)), float(second.get("time", 0))
    v0, v1 = float(first.get("value", 0)), float(second.get("value", 0))
    curve = first.get("curve")
    if not isinstance(curve, (list, tuple)):
        return [(t0, v0), (t1, v1)]
    cx1, cy1, cx2, cy2 = map(float, curve)
    points = [(t0, v0)]
    for index in range(1, 10):
        u = index / 10
        inverse = 1 - u
        points.append((inverse ** 3 * t0 + 3 * inverse ** 2 * u * cx1 +
                       3 * inverse * u ** 2 * cx2 + u ** 3 * t1,
                       inverse ** 3 * v0 + 3 * inverse ** 2 * u * cy1 +
                       3 * inverse * u ** 2 * cy2 + u ** 3 * v1))
    points.append((t1, v1))
    return points


def _segment_value(time: float, first: dict, second: dict) -> float:
    if first.get("curve") == "stepped":
        return float(second["value"] if time >= second.get("time", 0) else first["value"])
    points = _curve_nodes(first, second)
    for a, b in zip(points, points[1:]):
        if time <= b[0]:
            return a[1] + (b[1] - a[1]) * (time - a[0]) / (b[0] - a[0])
    return points[-1][1]


def _prepare_xy_38(x_frames: list[dict] | None, y_frames: list[dict] | None) -> tuple:
    """Keep sparse Beziers; preserve exceptional incompatible segments linearly.

    Unlike 4.x, 3.8 cannot give X/Y separate easing, or overshoot a channel
    whose endpoints are identical. In those cases only, retain the canonical
    runtime's nine interior curve samples as editable linear keys. These are
    curve breakpoints, independent of movie/export frame rate.
    """
    present = [frames for frames in (x_frames, y_frames) if frames]
    if not present:
        return x_frames, y_frames
    if len(present) == 2 and (len(present[0]) != len(present[1]) or
                             any(abs(a.get("time", 0) - b.get("time", 0)) > 1e-9
                                 for a, b in zip(*present))):
        raise ValueError("Spine 3.8 的 X/Y 曲線需共用相同的關鍵格時間。")
    output = [[] for _ in present]
    for index in range(len(present[0]) - 1):
        compatible = True
        choices = []
        try:
            for frames in present:
                first, second = frames[index], frames[index + 1]
                delta = abs(float(second["value"]) - float(first["value"]))
                choices.append((delta, _normalized_curve(first, second)))
            choices.sort(key=lambda item: item[0], reverse=True)
            selected = choices[0][1]
            for delta, other in choices[1:]:
                if delta < 1e-8:
                    continue
                if isinstance(selected, tuple) and isinstance(other, tuple):
                    compatible = compatible and max(abs(a - b) for a, b in zip(selected, other)) <= 1e-4
                else:
                    compatible = compatible and selected == other
        except ValueError:
            compatible = False
        if compatible:
            for target, frames in zip(output, present):
                target.append(copy.deepcopy(frames[index]))
            continue
        times = sorted({time for frames in present for time, _ in _curve_nodes(frames[index], frames[index + 1])})
        # A stepped channel cannot be interpolated together with a nonstepped
        # one exactly in 3.8; this tool never emits that unsupported mixture.
        if any(frames[index].get("curve") == "stepped" for frames in present):
            raise ValueError("Spine 3.8 無法合併階梯與連續的 X/Y 曲線。")
        for target, frames in zip(output, present):
            for time in times[:-1]:
                target.append({"time": time, "value": _segment_value(time, frames[index], frames[index + 1])})
    for target, frames in zip(output, present):
        target.append(copy.deepcopy(frames[-1]))
    iterator = iter(output)
    return (next(iterator) if x_frames else None, next(iterator) if y_frames else None)


def _merge_xy_38(x_frames: list[dict] | None, y_frames: list[dict] | None,
                  default: float) -> list[dict]:
    x_frames, y_frames = _prepare_xy_38(x_frames, y_frames)
    active = x_frames or y_frames
    if not active:
        return []
    if x_frames and y_frames:
        if len(x_frames) != len(y_frames) or any(abs(float(a.get("time", 0)) - float(b.get("time", 0))) > 1e-9
                                                for a, b in zip(x_frames, y_frames)):
            raise ValueError("Spine 3.8 的 X/Y 曲線需共用相同的關鍵格時間。")
    result = []
    for index, source in enumerate(active):
        frame = {"time": source.get("time", 0),
                 "x": x_frames[index].get("value", default) if x_frames else default,
                 "y": y_frames[index].get("value", default) if y_frames else default}
        if index + 1 < len(active):
            choices = []
            for frames in (x_frames, y_frames):
                if frames:
                    delta = abs(float(frames[index + 1].get("value", default)) - float(frames[index].get("value", default)))
                    choices.append((delta, _normalized_curve(frames[index], frames[index + 1])))
            choices.sort(key=lambda item: item[0], reverse=True)
            selected = choices[0][1] if choices else None
            for delta, other in choices[1:]:
                if delta < 1e-8:
                    continue
                if isinstance(selected, tuple) and isinstance(other, tuple):
                    if max(abs(a - b) for a, b in zip(selected, other)) > 1e-4:
                        raise ValueError("Spine 3.8 無法共用這組不同的 X/Y Bezier 曲線。")
                elif selected != other:
                    raise ValueError("Spine 3.8 無法共用這組不同的 X/Y 曲線。")
            _set_curve_38(frame, selected)
        result.append(frame)
    return result


def _convert_animation_38(animation: dict) -> None:
    for slot in animation.get("slots", {}).values():
        if "rgba" in slot:
            slot["color"] = slot.pop("rgba")
            if any("curve" in frame for frame in slot["color"]):
                raise ValueError("尚未支援 Spine 3.8 的多通道非線性色彩曲線。")
    for name, tracks in list(animation.get("bones", {}).items()):
        converted = {}
        for target, x_name, y_name, default in (("translate", "translatex", "translatey", 0.0),
                                                 ("scale", "scalex", "scaley", 1.0),
                                                 ("shear", "shearx", "sheary", 0.0)):
            if x_name in tracks or y_name in tracks:
                converted[target] = _merge_xy_38(tracks.get(x_name), tracks.get(y_name), default)
        if "rotate" in tracks:
            frames = tracks["rotate"]
            converted["rotate"] = []
            for index, source in enumerate(frames):
                frame = {"time": source.get("time", 0), "angle": source.get("value", 0)}
                if index + 1 < len(frames):
                    _set_curve_38(frame, _normalized_curve(source, frames[index + 1]))
                converted["rotate"].append(frame)
        supported = {"translatex", "translatey", "scalex", "scaley", "shearx", "sheary", "rotate"}
        unsupported = set(tracks) - supported
        if unsupported:
            raise ValueError("尚未支援轉換這些 Spine 3.8 動畫欄位：" + ", ".join(sorted(unsupported)))
        animation["bones"][name] = converted
    if "drawOrder" in animation:
        animation["draworder"] = animation.pop("drawOrder")


def convert_skeleton(canonical: dict, version: str = CANONICAL_SPINE_VERSION) -> dict:
    """Convert this tool's canonical 4.0 output to the requested real schema."""
    version = normalize_spine_version(version)
    if version == CANONICAL_SPINE_VERSION:
        return canonical
    result = copy.deepcopy(canonical)
    result["skeleton"]["spine"] = version
    family = spine_family(version)
    if family == "3.8":
        # 3.8 already uses the same array-of-skins attachment layout. Its
        # scalar bone and slot-color timelines, however, are different.
        for animation in result.get("animations", {}).values():
            _convert_animation_38(animation)
        result["skeleton"]["fps"] = select_native_safe_fps(result, version)
    elif family == "4.2":
        # In 4.2 the deform timelines are nested under per-attachment timeline
        # maps. Leaving a 4.0 top-level deform object silently loses motion.
        for animation in result.get("animations", {}).values():
            deform = animation.pop("deform", None)
            if deform:
                animation["attachments"] = {
                    skin: {slot: {attachment: {"deform": frames}
                                  for attachment, frames in attachments.items()}
                           for slot, attachments in slots.items()}
                    for skin, slots in deform.items()
                }
        result["skeleton"]["fps"] = select_native_safe_fps(result, version)
    return result
